-- Synthetic, disposable local PostgreSQL database only. No production identities.
create schema auth;
create schema private;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('test.actor',true),'')::uuid$$;
create function auth.jwt() returns jsonb language sql stable as $$select jsonb_build_object('role',coalesce(nullif(current_setting('test.role',true),''),'authenticated'))$$;
create function public.current_business_date() returns date language sql stable as $$select date '2026-06-01'$$;
create function public.can_manage_staff_student(uuid,uuid) returns boolean language sql stable as $$select auth.uid()='00000001-0000-4000-8000-000000000001'::uuid and $1='00000002-0000-4000-8000-000000000001'::uuid$$;
create function public.is_company_staff(uuid,uuid) returns boolean language sql stable as $$select $1='00000001-0000-4000-8000-000000000001'::uuid and $2='00000002-0000-4000-8000-000000000001'::uuid$$;
create table public.students(id uuid primary key,company_id uuid not null,user_id uuid);
create table public.plans(id uuid primary key,company_id uuid not null,duration_days integer,duration_weeks integer,cycle_duration_days integer,updated_at timestamptz default now());
create table public.enrollments(id uuid primary key,student_id uuid references public.students(id),company_id uuid,plan_id uuid references public.plans(id),status text,start_date date,end_date date,training_start_date date,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.training_cycles(id uuid primary key default gen_random_uuid(),enrollment_id uuid references public.enrollments(id),student_id uuid,company_id uuid,cycle_number integer,start_date date,end_date date,duration_weeks integer,status text,name text,created_at timestamptz default now(),superseded_by_cycle_id uuid,superseded_at timestamptz,superseded_by uuid,superseded_previous_status text,superseded_reason text,delivery_status text,prescribed_offline_at timestamptz,prescribed_offline_by uuid,prescribed_offline_note text,prescription_cleared_at timestamptz,anamnese_id uuid,bundle_id uuid,notes text,objective text,workouts jsonb default '[]');
create unique index training_cycles_enrollment_number_uidx on public.training_cycles(enrollment_id,cycle_number) where enrollment_id is not null;
create unique index training_cycles_one_active_per_enrollment_idx on public.training_cycles(enrollment_id) where status='active' and superseded_by_cycle_id is null;
create table public.workouts(id uuid primary key default gen_random_uuid(),cycle_id uuid references public.training_cycles(id),exercises jsonb,superseded_at timestamptz);
create table public.workout_sessions(id uuid primary key default gen_random_uuid(),workout_id uuid references public.workouts(id));
create table public.workout_logs(id uuid primary key default gen_random_uuid(),workout_id uuid references public.workouts(id));
create table public.prescription_bundles(id uuid primary key default gen_random_uuid(),training_cycle_id uuid references public.training_cycles(id),status text);
create table public.prescription_bundle_items(id uuid primary key default gen_random_uuid(),entity_type text,entity_id uuid);
create table public.cycle_feedback(id uuid primary key default gen_random_uuid(),cycle_id uuid references public.training_cycles(id));
create table public.ai_plan_versions(id uuid primary key default gen_random_uuid(),cycle_id uuid references public.training_cycles(id));
create table public.ai_strength_plans(id uuid primary key default gen_random_uuid(),training_cycle_id uuid references public.training_cycles(id));
create table public.running_plans(id uuid primary key default gen_random_uuid(),training_cycle_id uuid references public.training_cycles(id));
create table public.nutrition_plans(id uuid primary key default gen_random_uuid(),training_cycle_id uuid references public.training_cycles(id));
create table public.cycle_attachments(id uuid primary key default gen_random_uuid(),cycle_id uuid references public.training_cycles(id));
create table private.training_cycle_rebase_authorizations(transaction_id bigint,enrollment_id uuid);
